import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"Remove the Gemini stages from the pipeline","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/2026-10-03-remove-gemini-stages.md","filePath":"decisions/2026-10-03-remove-gemini-stages.md"}`),a={name:`decisions/2026-10-03-remove-gemini-stages.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="remove-the-gemini-stages-from-the-pipeline" tabindex="-1" dir="auto">Remove the Gemini stages from the pipeline <a class="header-anchor" href="#remove-the-gemini-stages-from-the-pipeline" aria-label="Permalink to “Remove the Gemini stages from the pipeline”">​</a></h1><ul><li dir="auto">Status: accepted</li><li dir="auto">Date: 2026-10-03</li></ul><h2 id="context" tabindex="-1" dir="auto">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p dir="auto">Gemini was the agent of two pipeline stages: the security review (<code>security.yml</code>) and the fix loop (<code>fix.yml</code>). The pipeline no longer uses any Google or Gemini service.</p><h2 id="decision" tabindex="-1" dir="auto">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p dir="auto">Both stages are removed, with everything that existed only for them: the two workflows and prompts, the <code>stage:reviewing</code> and <code>stage:fixing</code> stages and the <code>fix-loop:*</code> labels, the <code>fix-adapter</code>, <code>fix-reply</code>, <code>security-publish</code> and <code>gemini-billing</code> commands, the router&#39;s <code>retry</code> target, <code>/restart fixing</code>, the <code>pipeline/security</code> status, the HTTP 402 credit exception, the <code>.gemini/</code> config and its security check, and the <code>GEMINI_API_KEY</code> and <code>GEMINI_MODEL</code> settings.</p><p dir="auto">Claude (plan, develop) and Copilot (optional review) are unchanged. The flow after a draft PR opens is now: CI, then <code>approval.yml</code> evaluates the gates (CI, review threads, Copilot when required, protected-file approval) and hands the PR to a human. <code>approval.yml</code> runs when CI completes on a PR (it used to run on the <code>pipeline/security</code> status). <code>ci-failed.yml</code> is what is left of <code>security.yml</code>.</p><h2 id="consequences" tabindex="-1" dir="auto">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li dir="auto">No automated security review and no automated fixing of review comments: every review thread is resolved or dispositioned (<code>/disposition</code>, Copilot threads only) by a person, and the code owner still reviews and merges.</li><li dir="auto">A PR parked in <code>stage:needs-attention</code> is no longer moved on by a green CI run. Take it over by hand and run <strong>Pipeline · Approval</strong>.</li><li dir="auto">Labels and Project Status options that only existed for the removed stages are not deleted by any workflow. Delete <code>stage:reviewing</code>, <code>stage:fixing</code>, <code>fix-loop:1</code>, <code>fix-loop:2</code> and the <strong>Reviewing</strong> and <strong>Fixing</strong> Project options in the repo settings, and the <code>GEMINI_API_KEY</code> secret (also as a Dependabot secret) and the <code>GEMINI_MODEL</code> variable.</li></ul>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};